	{
		if (currentState + 1 >= (int)stack.size())
			return false;
		name = stack[currentState + 1].name;
		return true;
	}

	template<typename T>
	T* StateStack<T>::redo()
	{
		return currentState + 1 >= (int)stack.size() ? NULL : stack[++currentState].redoState;
	}

	template<typename T>
	size_t StateStack<T>::getStackSize() const
	{
